import calendar
from datetime import date, timedelta


def recur(start: str, rule: str, count: int) -> list[str]:
    start_date = date.fromisoformat(start)
    parts = rule.split(" ")
    freq = parts[0]
    k = int(parts[1])

    weekday_map = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}

    results = []

    if freq == "DAILY":
        curr = start_date
        while len(results) < count:
            results.append(curr.isoformat())
            curr += timedelta(days=k)

    elif freq == "WEEKLY":
        target_wds = sorted(weekday_map[code] for code in parts[2].split(","))
        start_monday = start_date - timedelta(days=start_date.weekday())
        week_idx = 0
        while len(results) < count:
            base_monday = start_monday + timedelta(weeks=week_idx * k)
            for wd in target_wds:
                candidate = base_monday + timedelta(days=wd)
                if candidate >= start_date:
                    results.append(candidate.isoformat())
                    if len(results) == count:
                        break
            week_idx += 1

    elif freq == "MONTHLY":
        start_year = start_date.year
        start_month = start_date.month

        if len(parts) == 3:
            # MONTHLY K D
            d_val = int(parts[2])
            month_idx = 0
            while len(results) < count:
                total_months = (start_year * 12 + (start_month - 1)) + month_idx * k
                year = total_months // 12
                month = total_months % 12 + 1
                _, max_days = calendar.monthrange(year, month)

                target_day = max_days if d_val == -1 else d_val
                if 1 <= target_day <= max_days:
                    candidate = date(year, month, target_day)
                    if candidate >= start_date:
                        results.append(candidate.isoformat())
                month_idx += 1

        else:
            # MONTHLY K N WD
            n_val = int(parts[2])
            target_wd = weekday_map[parts[3]]
            month_idx = 0
            while len(results) < count:
                total_months = (start_year * 12 + (start_month - 1)) + month_idx * k
                year = total_months // 12
                month = total_months % 12 + 1
                first_weekday, num_days = calendar.monthrange(year, month)

                matching_days = [
                    d for d in range(1, num_days + 1)
                    if (first_weekday + d - 1) % 7 == target_wd
                ]

                candidate_day = None
                if n_val == -1 and matching_days:
                    candidate_day = matching_days[-1]
                elif 1 <= n_val <= len(matching_days):
                    candidate_day = matching_days[n_val - 1]

                if candidate_day is not None:
                    candidate = date(year, month, candidate_day)
                    if candidate >= start_date:
                        results.append(candidate.isoformat())
                month_idx += 1

    elif freq == "YEARLY":
        target_mm, target_dd = map(int, parts[2].split("-"))
        year_idx = 0
        while len(results) < count:
            year = start_date.year + year_idx * k
            try:
                candidate = date(year, target_mm, target_dd)
                if candidate >= start_date:
                    results.append(candidate.isoformat())
            except ValueError:
                pass
            year_idx += 1

    return results
